INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Лечение с импланти',
'<p>Когато се загуби зъб, празнината в устата не остава непроменена. Съседните зъби могат с времето да се наклонят към празнината, зъбът от срещуположната челюст може да се удължи, а дъвкателното натоварване се разпределя неравномерно върху останалите зъби. Костта на челюстта в областта на празнината също може с времето да загуби обем, тъй като натоварването върху нея изчезва. Затова възстановяването на липсващ зъб най-често не е избор, свързан само с външния вид.</p>
<p>Денталният имплант е изкуствен корен, поставян в челюстната кост на мястото на липсващия зъб. Върху него може да се изработи единична корона, мост, носещ няколко зъба, или неподвижна конструкция, обхващаща цялата челюст. Задачата на импланта е да замести загубения корен и да поддържа конструкцията от костта.</p>
<h2>Не всеки липсващ зъб се възстановява с имплант</h2>
<p>Имплантът не е единствената възможност при липсващи зъби. Могат да се обсъдят и мост, опрян на зъбите, подвижна частична протеза, а в някои случаи — ортодонтско затваряне на празнината. Коя възможност е подходяща, се определя чрез съвместна оценка на позицията и размера на празнината, състоянието на съседните зъби, обема и качеството на костта, здравето на венците, оклузалните отношения, общото здравословно състояние и ежедневните навици за грижа.</p>
<p>Тази оценка се извършва чрез преглед, необходимите образни методи и протетично планиране. Категорична информация за пригодността, дадена по телефон, съобщение или по снимка, не е надеждна.</p>
<h2>Лечението не е една процедура, а процес</h2>
<p>Лечението с импланти обикновено се състои от следните етапи: преглед и образна диагностика, изготвяне на план на лечение, при необходимост подготвителни процедури, поставяне на импланта, период на зарастване за срастването на импланта с костта, изработване на протетичната конструкция и редовни контролни прегледи.</p>
<p>Продължителността на тези етапи се различава значително при отделните хора. Случай с достатъчен костен обем не протича по същия график като случай, изискващ костна присадка. Затова не се поема ангажимент за фиксиран срок; предполагаемите етапи се съобщават след прегледа.</p>
<h2>Дългосрочният резултат не се определя от един фактор</h2>
<p>Дали имплантът ще функционира дълги години, зависи от правилния подбор на случая, планирането, хирургичното и протетичното изпълнение, оралната хигиена, тютюнопушенето, общото здравословно състояние и редовните прегледи. Ако някой от тези фактори бъде пропуснат, резултатът може да пострада. Тъканите около импланта също могат да се възпалят, както при естествените зъби; с края на лечението грижата не приключва.</p>
<h2>Какво се проверява преди импланта?</h2>
<p>При прегледа не се гледа само областта на липсващия зъб. Оценяват се състоянието на останалите зъби, здравето на венците, оклузалните отношения и евентуален навик за стискане и скърцане със зъби. Ако има заболяване на венците, то се лекува преди имплантирането, тъй като тъканите около импланта се повлияват от същата бактериална плака.</p>
<p>Медицинската анамнеза също е част от планирането. Неконтролиран диабет, някои лекарства, влияещи върху костния метаболизъм, нарушения в кръвосъсирването, проведена лъчетерапия и тютюнопушене са теми, които могат да повлияят на зарастването. Нито една от тях сама по себе си не е абсолютна пречка; те обаче могат да променят планирането и очаквания ход. Затова е важно още при първия разговор да съобщите приеманите лекарства и известните заболявания.</p>
<h2>Протетиката не се мисли след импланта</h2>
<p>Често срещано погрешно схващане е, че първо се поставя имплантът, а зъбът върху него се планира после. Редът всъщност е обратен: първо се определя кой зъб, в каква форма и къде ще бъде изработен; позицията и наклонът на импланта се избират според този план. Това се нарича протетично насочено планиране.</p>
<p>Практическият смисъл на този подход е следният: дори неправилно поставен имплант да срасне безпроблемно с костта, върху него може да се окаже невъзможно да се изработи правилен, почистваем и естетичен зъб. Затова етапът на планиране не е по-маловажен от хирургичния.</p>
<h2>Страници в този раздел</h2>
<h3>В началото на лечението с импланти</h3>
<ul>
<li><a href="/bg/dental-implant-tedavisi/">Дентални импланти</a> — функцията на импланта, за кого може да се обсъжда, етапите на лечение и периодът на зарастване.</li>
<li>Възможности при липсващи зъби — разликите между имплант, мост и подвижна протеза. <em>(в подготовка)</em></li>
<li>План на лечение с импланти и неговият обхват — какво определя плана на лечение. <em>(в подготовка)</em></li>
<li>Кога имплант след екстракция? — критериите, които определят момента. <em>(в подготовка)</em></li>
</ul>
<h3>Ако костта е недостатъчна</h3>
<ul>
<li>Костна присадка и увеличаване на костния обем — методи, които се обсъждат при недостатъчен костен обем. <em>(в подготовка)</em></li>
<li>Синус лифт — подходът при ограничена височина на костта в задния участък на горната челюст. <em>(в подготовка)</em></li>
</ul>
<h3>Протетична конструкция</h3>
<ul>
<li>Неподвижни конструкции върху импланти — възможности за единична корона, мост и неподвижна конструкция за цяла челюст. <em>(в подготовка)</em></li>
<li>All-on-4 и All-on-6 — неподвижна конструкция за цяла челюст с ограничен брой импланти. <em>(в подготовка)</em></li>
</ul>
<h3>Процедура и зарастване</h3>
<ul>
<li>Болезнено ли е лечението с импланти? — местна упойка и период на зарастване. <em>(в подготовка)</em></li>
<li>Първите дни след имплантирането — болка, оток, кървене, хранене и грижа. <em>(в подготовка)</em></li>
</ul>
<h3>Дългосрочна грижа</h3>
<ul>
<li>Как се почиства имплант? — ежедневна рутина и интердентална четка. <em>(в подготовка)</em></li>
<li>Импланти при тютюнопушене и диабет — влиянието на тези два фактора върху зарастването. <em>(в подготовка)</em></li>
</ul>
<h3>Ако възникне проблем</h3>
<ul>
<li>Защо имплантът не се захваща? — причини за ранна и късна загуба на имплант. <em>(в подготовка)</em></li>
<li>Периимплантит — възпаление и костна загуба около импланта. <em>(в подготовка)</em></li>
</ul>
<h2>Често задавани въпроси</h2>
<p><strong>Подходящ ли е имплантът за всеки?</strong><br>Пригодността се определя чрез съвместна оценка на обема и качеството на челюстната кост, здравето на венците, общото здравословно състояние, приеманите лекарства, тютюнопушенето и оралната хигиена. Без преглед и образна диагностика решение не може да се вземе.</p>
<p><strong>Откъде да започна?</strong><br>Първата стъпка е прегледът. След съвместна оценка на Вашето оплакване, находките в устната кухина и необходимата образна диагностика Ви се съобщават възможностите и предполагаемите етапи.</p>
<p><strong>Колко импланта ще са необходими?</strong><br>Броят на липсващите зъби сам по себе си не е определящ. Заедно се оценяват разпределението на костта, оклузалното натоварване, планираният вид конструкция и естетичните изисквания. Преди прегледа не се поема ангажимент за брой.</p>
<p><strong>Нужна ли е специална грижа след имплантиране?</strong><br>Да. Тъканите около импланта също могат да се възпалят. Ежедневното почистване, интерденталната хигиена и редовните прегледи влияят пряко върху дългосрочния резултат.</p>
<p><strong>Възрастта ми пречка ли е за имплант?</strong><br>Няма горна възрастова граница; определящи са не възрастта, а костната и венечната опора и общото здравословно състояние. При долната граница се очаква растежът на челюстите да е завършил.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт пригодността за имплант се определя чрез съвместна оценка на клиничния преглед, резултатите от необходимата образна диагностика и протетичното планиране. След оценката възможностите и предполагаемите етапи се предоставят писмено.</p>
<p><a href="/bg/agiz-cerrahisi-uygulamalari/">Орална хирургия</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'Какво представлява лечението с импланти, за кого е подходящо и от какви етапи се състои? Планиране, хирургия, протетика и дългосрочна грижа.',
'Лечение с импланти | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'implant';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Естетична дентална медицина',
'<p>Естетичната дентална медицина цели цветът, формата и подреждането на зъбите да бъдат в хармония с лицето. Основата, върху която стъпва тази работа, обаче винаги е оралното здраве. Ако има активен кариес, възпаление на венците, нелекуван проблем с корен или небалансирана оклузия, естетичната процедура не се изгражда върху тях; първо се решават тези проблеми.</p>
<p>Причината не е само правило. Ръбът на възстановяване, изработено до възпалено венче, може с времето да се оголи, а при пропуснат навик за стискане новата керамика може да се повреди по-рано от очакваното. Затова естетичното планиране започва с преглед.</p>
<h2>Един метод не е подходящ за всички</h2>
<p>На двама души с едно и също оплакване може да не се предложи едно и също лечение. При потъмнял зъб понякога е достатъчно избелване, а понякога има подлежаща причина и е необходимо възстановително решение. При малка неравност във формата стига бондинг, докато при голяма загуба на тъкан се обсъжда корона. При проблеми с подреждането ортодонтската оценка може да е по-щадяща от възстановителната процедура.</p>
<p>При вземането на решение заедно се оценяват: оставащата здрава зъбна тъкан, количеството емайл, позицията на зъба в устата, основният цвят, нивата на венците, силата на оклузията, навикът за стискане и скърцане и очакванията на пациента. Целта е резултатът да се постигне с възможно най-щадящата опция.</p>
<h2>Как се планира естественият вид?</h2>
<p>Естественият резултат произтича от хармонията на цялото, а не от отделните зъби. Заедно се разглеждат пропорциите на зъбите, повърхностната текстура, светлопропускливостта, ходът на венечния ръб, линията на усмивката и отношението между устни и зъби. Само избелването на зъбите или изработването им с един и същ размер не дава естествен вид; определящо е отношението със съседните зъби и с лицето.</p>
<p>Венецът също е част от това цяло. Колко се вижда при усмивка, симетрията на нивата и здравето на тъканта влияят върху възприемането на резултата като естествен толкова, колкото и самите зъби.</p>
<h2>Очакванията и границите се обсъждат открито</h2>
<p>Един от най-важните етапи на естетичното лечение е споделянето на очакванията преди прегледа. При подходящи случаи дигиталното планиране и предварителният преглед позволяват да се добие представа за възможния резултат. Предварителният преглед е инструмент за планиране; той не е ангажимент за идентичен резултат.</p>
<p>Цветовото поведение на керамичните и композитните материали се различава от естествените зъби: естественият зъб променя цвета си с времето, докато възстановяването може да остане същото. Затова, ако избелване и възстановяване се планират заедно, редът има значение. По същия начин за нито едно възстановяване не може да се посочи фиксиран срок на употреба; резултатът се определя от грижата, оклузията и прегледите толкова, колкото и от избора на материал.</p>
<h2>Редът променя резултата</h2>
<p>В естетичното лечение редът на процедурите е също толкова важен, колкото и самата процедура. Общият подход е следният: първо се решават проблемите с оралното здраве, след това при нужда се коригира подреждането, после се работи по цвета, а накрая се завършват възстановителните процедури.</p>
<p>Причината за този ред е практическа. Ако зъбите ще бъдат коригирани ортодонтски, поставените преди това корони може да не пасват на новата позиция. Ако се планира избелване, възстановяванията във видимата зона трябва да се изберат според постигнатия нюанс; керамиката и композитът не се повлияват от избелването.</p>
<h2>Кога по-малкото е по-добро?</h2>
<p>В естетичната дентална медицина най-добрият резултат не винаги идва от най-обширната процедура. Здравият емайл, веднъж отстранен, не се връща; затова, ако същият резултат може да се постигне по по-щадящ път, се избира именно той.</p>
<p>Например: при малка фрактура на един зъб вместо корона може да се обсъди бондинг; при леко оплакване от цвета вместо възстановяване може да стигне избелване; разстоянието между зъбите в някои случаи може да се затвори ортодонтски. Всяка от тези възможности не е подходяща за всеки случай, но трябва да бъдат оценени заедно при прегледа. Ако Ви се предлага само една възможност, имате право да попитате защо алтернативите не са подходящи.</p>
<h2>Страници в този раздел</h2>
<h3>Планиране</h3>
<ul>
<li><a href="/bg/gulus-tasarimi/">Индивидуален дизайн на усмивката</a> — процесът на планиране, при който зъбите, венците, устните и пропорциите на лицето се оценяват заедно.</li>
<li>Златното сечение в дизайна на усмивката — къде правилата за пропорции са полезни. <em>(в подготовка)</em></li>
<li>Розова естетика и оформяне на венците — нива на венците и симетрия. <em>(в подготовка)</em></li>
</ul>
<h3>Корони и фасети</h3>
<ul>
<li><a href="/bg/zirkonyum-dis-kaplama/">Циркониеви корони</a> — области на приложение, дигитален работен процес, възможности за материали и грижа.</li>
<li>E.max и керамични фасети — показания при литиев дисиликат и фасети. <em>(в подготовка)</em></li>
<li>Фасета или цирконий? — сравнение на двете възможности. <em>(в подготовка)</em></li>
</ul>
<h3>По-щадящи възможности</h3>
<ul>
<li>Бондинг и естетични композитни обтурации — щадящ подход при ограничени корекции на форма и цвят. <em>(в подготовка)</em></li>
<li><a href="/bg/dis-beyazlatma/">Избелване на зъби</a> — кабинетни, домашни и комбинирани методи; управление на чувствителността.</li>
</ul>
<h2>Често задавани въпроси</h2>
<p><strong>Откъде да започна, от какво лечение се нуждая?</strong><br>Отправната точка е оценката за дизайн на усмивката. След съвместно разглеждане на Вашите очаквания, находките за оралното здраве и оклузията се обяснява кои процедури са подходящи и дали има по-щадяща алтернатива.</p>
<p><strong>Задължително ли е да се изпиляват зъбите ми?</strong><br>Не. В някои случаи са достатъчни възможности, които не изискват изпиляване, като избелване или бондинг. Обемът на подготовката зависи от настоящата структура на зъба и избраното възстановяване.</p>
<p><strong>Първо избелване или корона?</strong><br>Ако се планира избелване на естествените зъби, възстановяванията във видимата зона обикновено се изработват след избелването и според постигнатия нюанс. Възстановителните материали не променят цвета си като естествен зъб.</p>
<p><strong>Колко трае резултатът?</strong><br>Не може да се посочи фиксиран срок. Върху резултата влияят изборът на материал, останалата тъкан, оклузалното натоварване, навикът за стискане, оралната хигиена и редовните прегледи.</p>
<p><strong>Стискам зъбите си, възможна ли е естетична процедура?</strong><br>Навикът за стискане и скърцане влияе върху планирането и се оценява първо. Ако се прецени за необходимо, предпазната нощна шина става част от плана.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт възможностите за естетично лечение се оценяват заедно с оралното здраве, запазването на зъбната тъкан, оклузалните отношения и целта за естествен вид.</p>
<p><a href="/bg/iletisim">Час и контакти</a></p>',
'Дизайн на усмивката, цирконий, фасети, бондинг и избелване; вижте тук какво се обсъжда при всяка ситуация.',
'Естетична дентална медицина | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'estetik';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Орално и дентално здраве',
'<p>За посещение при зъболекар най-често се изчаква болка. Всъщност болката в много случаи не е началото на процеса, а неговата напреднала фаза. Кариесът не боли, когато започва в емайла; гингивитът, ранният стадий на заболяването на венците, може да не дава друг признак освен кървене. Затова редовните прегледи позволяват лечението да завърши с по-малка намеса и по-малка загуба на тъкан.</p>
<p>Този раздел обхваща местата, където оралното здраве се пресича с ежедневието: кариес и обтурации, проблеми с венците, болка и спешни състояния, чувствителност, оплаквания от челюст и мускули, ежедневни навици за грижа и денталното здраве на децата.</p>
<h2>Устната кухина не е независима от останалата част на тялото</h2>
<p>Връзката между заболяването на венците и диабета е двупосочна: неконтролираната кръвна захар може да повлияе на венечната тъкан, а продължаващото възпаление на венците затруднява гликемичния контрол. По същия начин хормоналните промени при бременност могат да направят венеца по-чувствителен към плаката. Някои лекарства причиняват сухота в устата и така повишават риска от кариес.</p>
<p>Затова при прегледа не се гледат само зъбите. Медицинската анамнеза, приеманите лекарства и евентуалните общи заболявания са част от планирането. При нужда се осъществява координация със съответния лекар.</p>
<h2>Ежедневната грижа е продължение на лечението</h2>
<p>Никоя процедура в кабинета не замества грижата у дома. Ако след отстраняване на зъбния камък натрупването на плака продължи, възпалението на венците се връща; ако в уста с обтурации рискът от кариес не се управлява, се появяват нови кариеси. Затова техниката на четкане, интерденталното почистване, изборът на паста и режимът на хранене са също толкова важни, колкото и лечението.</p>
<p>Правилното средство не е едно и също за всички. Широчината на междузъбните пространства, наличието на протеза или имплант, сръчността и навиците може да изискват различни средства.</p>
<h2>При болка и спешни състояния изчакването вреди</h2>
<p>Силна зъбна болка, оток на лицето, температура, фрактура след травма или избит зъб са състояния, които не бива да се отлагат. Особено при избит постоянен зъб първите минути са решаващи. Денталната травма при деца изисква напълно различен подход в зависимост от това дали става дума за временен или постоянен зъб.</p>
<h2>Границата между лечение и профилактика</h2>
<p>Повечето процедури в денталната медицина запълват мястото на загубена тъкан. Обтурацията замества кариозната тъкан, короната обхваща счупения зъб. Но нито една от тях не замества напълно естествената тъкан и нито една не остава завинаги. Затова истинската печалба в денталната медицина идва не толкова от качеството на процедурата, колкото от това изобщо да не се стигне до нея.</p>
<p>Профилактиката се състои от конкретни неща: правилна техника на четкане, интердентално почистване, намаляване на честотата на прием на захар, използване на флуорид и явяване на преглед през интервали, съобразени с нивото на риск. Това изглежда просто, но ефектите се натрупват.</p>
<h2>Защо подходът при децата е различен?</h2>
<p>Детската дентална медицина не е умален вариант на лечението при възрастни. Емайлът на временните зъби е по-тънък и кариесът може да напредва по-бързо. Рано загубен временен зъб може да стесни мястото, предвидено за постоянния зъб под него. При травма временният и постоянният зъб се третират напълно различно; избит временен зъб не се връща на мястото му.</p>
<p>Освен това успехът на лечението при детето зависи и от отношението му към самия процес. Дете, което е опознало кабинета в период без болка, обикновено по-лесно приема необходимото по-късно лечение. Затова целта на първото посещение обикновено не е лечение.</p>
<h2>Страници в този раздел</h2>
<h3>Кариес, обтурации и коренови канали</h3>
<ul>
<li><a href="/bg/kanal-tedavisi/">Кореново лечение</a> — в кои случаи се прилага, етапите му и възстановяването след него.</li>
<li><a href="/bg/dis-curugu-kompozit-dolgu/">Кариес и композитна обтурация</a> — как се разпознава кариесът и какви са лечебните възможности.</li>
</ul>
<h3>Първа стъпка и контрол</h3>
<ul>
<li><a href="/bg/ilk-dis-muayenesi-tedavi-planlamasi/">Първи преглед и планиране на лечението</a> — какво се оценява при прегледа.</li>
<li>Редовни прегледи — факторите, определящи честотата им. <em>(в подготовка)</em></li>
<li>Страх от зъболекар — подход към лечението при тревожни пациенти. <em>(в подготовка)</em></li>
</ul>
<h3>Венци</h3>
<ul>
<li>Отстраняване на зъбен камък и здраве на венците — как се образува зъбният камък и какво включва почистването. <em>(в подготовка)</em></li>
<li>Заболявания на венците — разликата между гингивит и пародонтит. <em>(в подготовка)</em></li>
</ul>
<h3>Болка, чувствителност и спешни случаи</h3>
<ul>
<li>Спешна зъбна болка — кога не се чака и какво се прави първо. <em>(в подготовка)</em></li>
<li>Чувствителност на зъбите — причини за реакция към студено и топло. <em>(в подготовка)</em></li>
</ul>
<h3>Деца и специални периоди</h3>
<ul>
<li><a href="/bg/cocuk-dis-hekimligi/">Детска дентална медицина</a> — възраст за първи преглед, кариес на временните зъби, флуорид.</li>
<li><a href="/bg/hamilelikte-dis-tedavisi/">Дентално лечение при бременност</a> — планиране по триместри и грижа у дома.</li>
<li><a href="/bg/cocuklarda-dis-travmasi/">Дентални травми при деца</a> — първите 30 минути при счупен или избит зъб.</li>
</ul>
<h2>Често задавани въпроси</h2>
<p><strong>Колко често да идвам на преглед?</strong><br>Няма един интервал за всички. Индивидуален интервал се определя след оценка на риска от кариес, състоянието на венците, оралната хигиена, тютюнопушенето и общите заболявания.</p>
<p><strong>Нямам болка, нужен ли е все пак преглед?</strong><br>Да. Ранният стадий на кариеса и началото на заболяването на венците най-често не болят. Проблем, открит рано, се лекува с по-малка намеса.</p>
<p><strong>Венците ми кървят при четкане, да спра ли да си мия зъбите?</strong><br>Не. В повечето свързани с плака ситуации спирането на почистването засилва възпалението. Трябва да продължите нежното и редовно почистване с мека четка и да си запазите час за преглед.</p>
<p><strong>Кога да доведа детето си за първи път?</strong><br>Препоръчва се в рамките на шест месеца след поникването на първия временен зъб, най-късно на първия рожден ден. Целта на това посещение най-често не е лечение, а оценка на риска и привикване.</p>
<p><strong>Коя паста за зъби да използвам?</strong><br>Изборът зависи от възрастта, риска от кариес, чувствителността и състоянието на венците. Какво е подходящо за Вас, се обяснява при прегледа.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт оценката на оралното здраве се прави чрез съвместно разглеждане на оплакванията, находките в устната кухина и необходимата образна диагностика; определя се индивидуален режим на грижа и прегледи.</p>
<p><a href="/bg/iletisim">Час и контакти</a></p>',
'Кариес, венци, зъбобол, чувствителност, ежедневна грижа и дентално здраве на децата; от прегледа до профилактичното лечение.',
'Орално и дентално здраве | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'agiz-dis-sagligi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Орална и лицево-челюстна хирургия',
'<p>Процедурите по орална хирургия изискват съвместна оценка на зъба, челюстната кост и околните структури. Позицията на зъба, формата на корена, отношението му към костта и съседните анатомични образувания се разкриват само чрез клиничен преглед и подходящи образни методи. Затова хирургична процедура не се планира с поглед в устата и заключението „трябва да се вади“.</p>
<p>В долната челюст върху планирането пряко влияе отношението между корените на зъба и мандибуларния канал, а в горната — съседството на зъбите със синусната кухина. Тези отношения в някои случаи се оценяват с панорамна снимка, а в други — с триизмерна образна диагностика.</p>
<h2>Не всеки ретиниран зъб се вади</h2>
<p>Мъдреците, когато не намират място в устата, могат да пробият частично или да останат ретинирани в костта. Това не винаги изисква екстракция. Екстракцията се обсъжда при болка, повтаряща се инфекция, увреда на съседния зъб, съмнение за киста, позиция, която не позволява почистване, или изискване на друго планирано лечение. При зъби, които не създават оплаквания и могат да бъдат проследявани, може да се предпочете наблюдение.</p>
<p>Същият подход важи и за хирургичната екстракция: първо се оценява възможността зъбът да бъде спасен. Когато зъбът може да се запази чрез кореново лечение, резекция на върха на корена или възстановително решение, екстракцията не е първата възможност.</p>
<h2>Рисковете се обясняват от самото начало</h2>
<p>Оток, чувствителност, ограничено отваряне на устата и затруднено дъвчене след хирургични процедури са очаквани прояви. Те не са усложнения, а обичайна част от зарастването и обикновено са изразени през първите дни. Освен това всяка процедура има собствени рискове: свързани с анатомичното съседство, кървене, инфекция и по-бавно от очакваното зарастване.</p>
<p>Индивидуалното обясняване на тези рискове е част от процедурата. Кои прояви са очаквани и кои изискват незабавно посещение, се съобщава преди и след процедурата.</p>
<h2>Костният обем е част от имплантологичното планиране</h2>
<p>Значителна част от оралната хирургия е преплетена с лечението с импланти. Ако зъбът е загубен отдавна, костният обем в тази област може да е намалял. В такива случаи преди импланта може да се наложи увеличаване на костния обем или повдигане на пода на синуса в задния участък на горната челюст. Това не е необходимо при всеки пациент; нуждата се определя чрез съвместна оценка на образната диагностика и протетичния план.</p>
<h2>Процесът на планиране се обяснява ясно</h2>
<p>Обхватът и условията за провеждане на всяка хирургична процедура са различни. След оценката се определя при какви условия и с какъв екип процедурата е подходяща; това планиране се обяснява ясно на пациента и решението се взема заедно.</p>
<p>MSc. Dt. Mehmet Taş след обучението си във Факултета по дентална медицина на Истанбулския университет завърши магистратура в Италия в областта на оралната хирургия и имплантологията. Това образование не е специалност; то изгражда научната основа на подхода, следван при хирургичното и имплантологичното планиране.</p>
<h2>Подготовка преди процедурата</h2>
<p>Преди всяка хирургична процедура трябва да се съобщи следното: известни заболявания, редовно приемани лекарства, алергии, прекарани операции и евентуално състояние, свързано с кървене. Кръворазреждащите лекарства, средствата, влияещи върху костния метаболизъм, и имуносупресивните терапии влияят пряко върху планирането.</p>
<p>Тези лекарства не бива да се спират без лекарска препоръка. При нужда, в координация със съответния лекар, се определят моментът и методът на процедурата.</p>
<h2>Какво да очакваме в периода на зарастване?</h2>
<p>Първите дни от зарастването протичат различно от следващите седмици. Първите 24 часа са важни за защитата на съсирека: препоръчва се областта да не се натоварва, да не се изплаква енергично, да не се пие със сламка и да се избягва тютюнопушенето. Отокът обикновено нараства през първите дни, а след това намалява. Възможно е временно ограничение в отварянето на устата.</p>
<p>Това са очаквани прояви. За сметка на това нарастваща и непреминаваща болка, висока температура, обширен оток, неприятна миризма или секрет, затруднено преглъщане или дишане изискват незабавно посещение.</p>
<h2>Страници в този раздел</h2>
<ul>
<li><a href="/bg/agiz-cerrahisi-uygulamalari/">Орална хирургия</a> — обхват, предоперативна оценка, зарастване и обясняване на рисковете.</li>
<li>Ретиниран мъдрец — в кои случаи се обсъжда екстракция и в кои наблюдение. <em>(в подготовка)</em></li>
<li>Костна присадка и увеличаване на костния обем — методи и зарастване при недостиг на кост. <em>(в подготовка)</em></li>
<li>Синус лифт — подходът при ограничена височина на костта в задния участък на горната челюст. <em>(в подготовка)</em></li>
</ul>
<h2>Често задавани въпроси</h2>
<p><strong>Мъдрецът ми не боли, да го вадя ли все пак?</strong><br>Ако няма оплакване, екстракцията не е автоматично необходима. Дали е подходяща екстракция или наблюдение, се решава след оценка на позицията на зъба, възможността за почистване, влиянието върху съседния зъб и рентгеновите находки.</p>
<p><strong>Усеща ли се болка по време на процедурата?</strong><br>Процедурата се извършва под местна упойка и целта е комфорт. Възможно е усещане за натиск и вибрация. Тъй като личното преживяване може да е различно, категорична гаранция за безболезненост не се дава.</p>
<p><strong>Колко трае отокът?</strong><br>Отокът обикновено е изразен през първите дни и постепенно намалява. Продължителността зависи от обхвата на процедурата и от пациента. При нарастваща болка, температура или обширен оток трябва да се потърси помощ без изчакване.</p>
<p><strong>Приемам кръворазреждащо лекарство, възможна ли е процедурата?</strong><br>Съобщете приеманите лекарства. Кръворазреждащите лекарства не бива да се спират без лекарска препоръка; при нужда планирането се прави заедно със съответния лекар.</p>
<p><strong>Нужна ли е костна присадка при всеки имплант?</strong><br>Не. Нуждата се определя чрез съвместна оценка на наличния костен обем и планираната конструкция; в повечето случаи допълнителна процедура не е необходима.</p>
<p><strong>Мога ли да отида на работа или училище след процедурата?</strong><br>Зависи от обхвата на процедурата. През първия ден може да се препоръча почивка. Индивидуалните препоръки се съобщават преди процедурата.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт нуждата от хирургия се определя чрез съвместна оценка на клиничния преглед, необходимите образни методи и анатомичните съседства. След оценката подходящият план на лечение се определя заедно с пациента.</p>
<p><a href="/bg/dental-implant-tedavisi/">Дентални импланти</a> · <a href="/bg/kanal-tedavisi/">Кореново лечение</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'Ретиниран мъдрец, хирургична екстракция, увеличаване на костния обем и синус лифт; оценка, планиране на процедурата и период на зарастване.',
'Орална и лицево-челюстна хирургия | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'cerrahi';

